// Do not edit it: change the doc comments of the Rust types, then run `tomet spec schema` and
// `tomet spec typescript` again (`just docs`).
//
// What the functions of `@tomet/wasm` take and return besides a document. The AST it refers to is `ast.d.ts`.
import type { Declaration, PlainValue, Span } from "./ast.js";

/**
 * Something wrong with a document, or something it says about itself: what `tomet check` reports,
 * plus the links a page could not be given a target for.
 *
 * What found it does not matter to whoever reads it: a document that does not read as the
 * vocabulary says, a link that goes nowhere and an expression that has no value all come as this.
 */
export interface Diagnostic {
  /**
   * What kind of finding it is, in lower case with hyphens: `unknown-element`, `dangling-anchor`,
   * `draft`, `unresolved-link`, `unresolved-expression`. Stable: a tool can tell findings apart by it.
   */
  code: string;
  /** How much it matters. */
  severity: Severity;
  /** What it says, in words, for a person. */
  message: string;
  /** Where it is, as a range of bytes of the source. */
  span: Span;
  /**
   * Where it starts, as a line and a column. `null` when the document was given as a tree and not as
   * text, so there is no text to count in.
   */
  start: Position | null;
  /** Where it ends, as a line and a column. `null` as `start` is. */
  end: Position | null;
}

/** A range of the source to color. Offsets are bytes of the source. */
export interface HighlightSpan {
  /** Where the range starts. */
  from: number;
  /** Where the range ends, exclusive. */
  to: number;
  /** What the range is: `heading`, `bracket`, `tagName`, `string`, ... */
  tag: string;
  /** How deep the range is nested in brackets. */
  depth: number;
}

/** A place in the source, as a person counts it. */
export interface Position {
  /** The line, counted from 1. */
  line: number;
  /** The column, counted from 1, in characters. */
  column: number;
}

/** What to read one document with. Every field is optional. */
export interface ProcessOptions {
  /**
   * Number the headings (`1`, `1.1`, ...) and give each an `id` made from its text: the default
   * of `numberHeadings` and `autoSlugHeadings`, which switch each on its own.
   */
  advanced?: boolean | null;
  /** Number the headings. Defaults to `advanced`. */
  numberHeadings?: boolean | null;
  /** Give every heading an `id` made from its text. Defaults to `advanced`. */
  autoSlugHeadings?: boolean | null;
  /** The language of the page, for the `lang` of what is rendered. */
  lang?: string | null;
  /**
   * Where the document is in the vault, from the root of the files the vault was given: what a
   * `./` link, a note name and an expression such as `self::path` are read from.
   */
  currentPath?: string | null;
}

/**
 * What reading a document for a page gives.
 *
 * The document's `::meta` is seen through two windows:
 *
 * - `meta` is the data of it, as an object of plain data. An entry that is not data (an element such
 *   as `icon: @doc.icon("star")`, a call, `auto`, ...) is not in it: nothing stands in its place, and it
 *   is not an error. `meta` is `null` if the document writes no `::meta`, and `{}` if it writes one
 *   with no entry that is data.
 * - `header` is everything the document declares, `::meta` included, as the AST: where an application
 *   finds what `meta` leaves out, and interprets it. Tomet does not resolve an icon; the application does.
 *
 * Both are read after the expressions of the document are resolved.
 */
export interface ProcessedFile {
  /** The `title` of `::meta`, or else the first heading of level 1. `null` if there is neither. */
  title: string | null;
  /** The body, rendered. */
  html: string;
  /** The data of `::meta`: an object, or `null` if the document writes none. */
  meta: { [key: string]: PlainValue } | null;
  /** Everything the document declares. */
  header: Declaration[];
  /** The headings of level 2 and 3. */
  toc: TocItem[];
  /** Whether the document has nothing to show: it declares and holds data, and its body is empty. */
  is_data_only: boolean;
  /**
   * Everything found wrong with the document, or that it says about itself, in the order it is in
   * the text: what `tomet check` reports, a link or an embed that goes nowhere, an expression that
   * has no value. A page with a diagnostic of any severity is not as its author wrote it.
   */
  diagnostics: Diagnostic[];
}

/** The files the vault registers, which a host reads to make the `VaultSources` of it. */
export interface Registry {
  /** The vocabulary documents, as paths from the directory of the config. */
  vocabularies: string[];
  /** The dictionary documents, as paths from the directory of the config. */
  dictionaries: string[];
  /** The blueprint documents, as paths from the directory of the config. */
  blueprints: string[];
}

/** How much a diagnostic matters. */
export type Severity =
  /** The document is wrong. */
  | "error"
  /**
   * The document says something about itself, or leaves something unresolved, that a reader
   * should see; it is otherwise fine. `@draft`, `@fixme` and an expression that has no value are
   * warnings.
   */
  | "warning";

/**
 * Where the source of the project is on the web, for what a page has no page for: a `file:` or `dir:`
 * link to a file that is not a published document.
 */
export interface SourceUrls {
  /**
   * The URL of a file, with `{path}` where its path from the root of the vault goes (each segment
   * percent-encoded): `https://github.com/org/repo/blob/<revision>/{path}`.
   */
  file: string;
  /** The URL of a directory, with `{path}` as in `file`: `https://github.com/org/repo/tree/<revision>/{path}`. */
  dir: string;
}

/** An entry in the document's table of contents. */
export interface TocItem {
  /** The `id` of the heading, to link to it with `#id`. */
  id: string;
  /** The level of the heading: 2 or 3. */
  level: number;
  /** The text of the heading, without its number. */
  text: string;
}

/**
 * What a vault is made of. Everything is optional: `{}` is a vault of nothing, in which a document is
 * read with `std` alone and links go nowhere.
 */
export interface VaultSources {
  /**
   * The path of every file of the vault, from its root, with `/` between the segments. A `ref:` link
   * and an embed name one of them.
   */
  files?: string[];
  /**
   * The documents the site has a page for, a part of `files`. Defaults to every `.tmt`, `.tm` and
   * `.md` of `files`. A link to a document that is not here is a link to nothing.
   */
  documents?: string[] | null;
  /**
   * The settings, as the text of a config document (`vault.config.tmt`): macros, variables, and
   * the `type:` of `::meta` fields.
   */
  config?: string | null;
  /**
   * The vocabularies, as the text of the documents the config registers, by the path the config
   * gives them.
   */
  vocabularies?: { [key: string]: string };
  /** The dictionaries, as the text of the documents the config registers, by the path the config gives them. */
  dictionaries?: { [key: string]: string };
  /** The blueprints, as text. A document is checked against the one for its `::kind`. */
  blueprints?: string[];
  /** Where the pages of the site are: `/docs` gives `/docs/spec/syntax`. Defaults to `/docs`. */
  urlPrefix?: string | null;
  /** Where the files that are not documents are: `/vault` gives `/vault/img/x.png`. Defaults to `/vault`. */
  assetPrefix?: string | null;
  /**
   * Where the files given are in the vault, from its root, when they are a part of it: `tmtroot`
   * if the files are what is under `tmtroot/`. A path in a document is written from the root of the
   * vault, and this is what it is read from. Defaults to `""`: the files are the vault.
   */
  basePath?: string | null;
  /**
   * Where the source of the project is on the web. Without it, a link to a file that has no page is
   * a diagnostic.
   */
  sourceUrl?: SourceUrls | null;
}
